// Sample data for the community loop's pages, in the shapes of docs/community_loop_contract.md, until the loop's
// routes are on the gateway (see source() in api.js). It stands for what the end-to-end run on the simulated club
// produces: members and requests generated by code from seed 7. No real person is in it. Member ids are made-up
// HMAC-like strings; the texts follow the sharing rules (120 characters at most, no names, places, numbers, links or
// body or health terms).
// The state lives in memory, so votes, decisions and rollbacks work for the visit and are gone on reload.

const DAY = 864e5, HOUR = 36e5;
const now = Date.now();
export const SEED = 7;

// mulberry32, as in agent/src/population.js: the same seed, the same ids
function rng(seed) { let a = seed >>> 0; return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const r = rng(SEED);
const who = () => Array.from({ length: 64 }, () => "0123456789abcdef"[Math.floor(r() * 16)]).join("");
const BETA = Array.from({ length: 8 }, who);

// what each stage of the loop holds (the Agents Rule of Two: never all three at once)
const R = (stage, untrusted, priv, power) => ({ stage, untrusted, private: priv, power });
const TALK = [R("collect", true, true, false), R("screen", true, false, false), R("cluster", true, false, false), R("summarize", true, false, false), R("draft", true, false, false), R("review", false, false, false)];
const R2_C0 = [...TALK, R("gates", false, false, false), R("ship", false, true, true)];
const R2_CODE = [...TALK, R("build", false, false, true), R("gates", false, false, false), R("merge", false, false, true), R("ship", false, true, true)];

const G = (gate, ok, details) => ({ gate, ok, details });
const C0_GATES = (key, value, range) => ({
  pass: true,
  results: [
    G("policy", true, `No code diff. ${key} = ${value} is a declared key, inside its range ${range[0]}–${range[1]}.`),
    G("scan", true, "Nothing to scan: no code changed."),
    G("unit", true, "npm test: all passed with the new value."),
    G("crash_matrix", null, "Not needed: a C0 change runs no new code."),
    G("redteam", null, "Not needed: a C0 change runs no new code."),
    G("e2e", null, "Not needed: a C0 change runs no new code."),
    G("autopilot_eval", null, "Not needed: a C0 change runs no new code."),
    G("oracle", true, "The check is set up; it is read again when the canary ends."),
    G("privacy", true, "The body-log canary marker stayed out of every outbound request."),
  ],
});
const h = (ago, status, by, note) => ({ at: now - ago, status, by, ...(note ? { note } : {}) });

