let state = null;
const fresh = () => ({ specs: structuredClone(SPECS), clusters: structuredClone(CLUSTERS), flags: structuredClone(FLAGS), builds: structuredClone(BUILDS), mine: {}, credits: 9 });
const S = () => (state ||= fresh());
const wait = (ms) => new Promise((res) => setTimeout(res, ms));
const fail = (status, error) => Object.assign(new Error(error), { status });
// for checking the pages' other states: add mock=empty, mock=error or mock=slow to the page's address
const scenario = () => new URLSearchParams(location.hash.split("?")[1] || "").get("mock") || "";
async function answer(make) {
  const sc = scenario();
  await wait(sc === "slow" ? 6000 : 350);
  if (sc === "error") throw fail(503, "The sample server is set to fail (mock=error).");
  return structuredClone(make(S(), sc === "empty"));
}
const specOf = (s, id) => s.specs.find((p) => p.id === id);
const shippedAt = (p) => [...p.history].reverse().find((x) => x.status === "shipped")?.at;

// GET /api/loop/ideas
export const ideas = () => answer((s, empty) => {
  const clusters = empty ? [] : s.clusters.map((c) => {
    const p = c.proposal && specOf(s, c.proposal);
    return { ...c, title: p?.title ?? c.texts[0], status: p?.status ?? "open", reasons: p?.status === "refused" || p?.status === "rolledBack" ? p.reasons : [],
      score: 2 * c.unmet + c.wishes + c.votes, mine: s.mine[c.proposal ?? c.id] || 0, at: p ? shippedAt(p) : undefined };
  });
  const notes = clusters.filter((c) => c.status === "shipped").map((c) => ({ proposal: c.proposal, title: c.title, members: c.members, at: c.at, text: `Shipped, asked for by ${c.members} members` }));
  return { simulated: { seed: SEED, members: 40 }, credits: s.credits, of: 9, clusters, notes };
});

// POST /api/loop/vote { proposal, votes }: a member's votes on one idea, set (not added); n votes cost n² credits
export const vote = ({ proposal, votes }) => answer((s) => {
  const n = Math.max(0, Math.min(3, Math.floor(votes))), was = s.mine[proposal] || 0;
  const left = s.credits + was * was - n * n;
  if (left < 0) throw fail(400, `Not enough credits: ${n} votes cost ${n * n}, and you have ${s.credits + was * was} for this idea.`);
  s.mine[proposal] = n; s.credits = left;
  const c = s.clusters.find((x) => (x.proposal ?? x.id) === proposal);
  if (c) c.votes += n - was;
  const p = specOf(s, proposal);
  if (p) p.problem.votes += n - was;
  return { ok: true, credits: left };
});

// GET /api/loop/proposals
export const proposals = () => answer((s, empty) => (empty ? [] : s.specs));

// POST /api/loop/decide { proposal, decision, note } (maintainer)
export const decide = ({ proposal, decision, note }) => answer((s) => {
  const p = specOf(s, proposal);
  if (!p) throw fail(404, `No proposal ${proposal}.`);
  if (!["open", "review"].includes(p.status)) throw fail(409, `${proposal} is ${p.status}; only an open proposal or one in review can be decided.`);
  p.status = decision === "approve" ? "approved" : "refused";
  if (decision === "refuse") p.reasons = [note];
  p.history.push({ at: Date.now(), status: p.status, by: "maintainer", ...(note ? { note } : {}) });
  return p;
});

// GET /api/loop/flags
export const flags = () => answer((s, empty) => (empty ? {} : s.flags));

// GET /api/loop/builds (maintainer): the builder's work, by proposal; POST /api/loop/build { proposal } starts one,
// which in the sample stops at once: there is no model in the browser
export const builds = () => answer((s, empty) => ({ builds: empty ? {} : s.builds, gates: { run: ["policy", "scan", "unit", "oracle", "privacy"], all: ["policy", "scan", "unit", "crash_matrix", "redteam", "e2e", "autopilot_eval", "oracle", "privacy"] } }));
export const build = ({ proposal }) => answer((s) => {
  const p = specOf(s, proposal);
  if (!p) throw fail(404, `No proposal ${proposal}.`);
  if (p.status !== "approved" || !["C1", "C2", "C3"].includes(p.change.class)) throw fail(409, `${proposal} is ${p.status}; only an approved C1–C3 proposal is built.`);
  s.builds[proposal] = { proposal, status: "failed", phase: "build", startedAt: Date.now(), finishedAt: Date.now() + 1000, attempts: [], branch: null, diff: "", stat: "", class: p.change.class, files: p.change.files,
    gatesRun: [], gatesNotRun: [], infra: true, reasons: ["Sample data: there is no model server in the sample, so the build stopped before its first attempt. On your gateway it runs Muse Glimmer."] };
  return s.builds[proposal];
});

// POST /api/loop/rollback { key, reason } (maintainer)
export const rollback = ({ key, reason }) => answer((s) => {
  const f = s.flags[key];
  if (!f) throw fail(404, `No flag ${key}.`);
  if (f.status !== "canary" && f.status !== "on") throw fail(409, `${key} is ${f.status}; only a flag in canary or on can be rolled back.`);
  f.status = "rolledBack"; f.since = Date.now();
  f.history.push({ at: Date.now(), status: "rolledBack", value: f.default, by: "maintainer", reason });
  const p = f.proposal && specOf(s, f.proposal);
  if (p) { p.status = "rolledBack"; p.reasons = [reason]; p.history.push({ at: Date.now(), status: "rolledBack", by: "maintainer", note: reason }); }
  return { key, ...f };
});
